const dateLabel = (value: string | null, locale: string) => value ? new Date(`${value}T12:00:00`).toLocaleDateString(locale) : "—"
const localDateKey = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}` }
const cropKey = (crop: string, variety: string | null) => `${crop.trim().toLowerCase()}|${(variety ?? "").trim().toLowerCase()}`
const numeric = (value: string) => value === "" ? null : Number(value)
const estimatedSeeds = (item: Succession) => { const plants = item.planned_plants ?? 0; const germination = item.germination_rate_pct && item.germination_rate_pct > 0 ? item.germination_rate_pct : 100; const perPlant = item.seeds_per_plant && item.seeds_per_plant > 0 ? item.seeds_per_plant : 1; return Math.ceil((plants * perPlant) / (germination / 100)) }

export default function OrchardNurseryPage() {
  const supabase = useMemo(() => createBrowserClient(), [])
  const { language } = useLanguage(); const lang = language; const text = copy[lang]; const locale = locales[lang]
  const statusLabel = (value: BatchStatus) => statusLabels[lang][value]
  const adjustmentLabel = (value: AdjustmentType) => adjustmentLabels[lang][value]
  const movementLabel = (value: string) => movementLabels[lang][value] ?? value.replaceAll("_", " ")
  const [plans, setPlans] = useState<GamePlan[]>([]); const [selectedPlanId, setSelectedPlanId] = useState<string>(ALL_GAME_PLANS)
  const [seedLots, setSeedLots] = useState<SeedLot[]>([]); const [movements, setMovements] = useState<SeedMovement[]>([]); const [batches, setBatches] = useState<Batch[]>([]); const [successions, setSuccessions] = useState<Succession[]>([]); const [cycles, setCycles] = useState<Cycle[]>([])
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState<string | null>(null)
  const [lotForm, setLotForm] = useState({ crop_name: "", variety: "", lot_code: "", supplier: "", quantity_seeds: "", germination_rate_pct: "", received_date: "", expiry_date: "", storage_location: "", notes: "" })
  const [batchForm, setBatchForm] = useState({ crop_succession_id: "", seed_lot_id: "none", batch_code: "", sow_date: "", tray_count: "", cells_per_tray: "", cells_sown: "", seeds_sown: "", expected_ready_date: "", location: "", notes: "" })
  const [adjustmentForm, setAdjustmentForm] = useState({ seed_lot_id: "", movement_type: "receipt" as AdjustmentType, quantity_delta: "", reason: "", occurred_on: "" }); const [progress, setProgress] = useState<Record<string, Progress>>({})

  const loadData = useCallback(async () => {
    setLoading(true); setError(null)
    const [p, l, m, b, s, c] = await Promise.all([
      supabase.from("orchard_game_plans").select("id,name,season,start_date,end_date,status").order("start_date", { ascending: false }),
      supabase.from("orchard_seed_lots").select("id,crop_name,variety,lot_code,supplier,quantity_seeds,germination_rate_pct,received_date,expiry_date,storage_location,notes").order("crop_name"),
      supabase.from("orchard_seed_inventory_movements").select("id,seed_lot_id,nursery_batch_id,movement_type,quantity_delta,occurred_on,reason,created_at").order("created_at", { ascending: false }).limit(100),
      supabase.from("orchard_nursery_batches").select("id,crop_succession_id,seed_lot_id,batch_code,sow_date,tray_count,cells_per_tray,cells_sown,seeds_sown,emerged_count,loss_count,loss_reason,ready_count,hardened_count,transplanted_count,expected_ready_date,actual_ready_date,hardening_started_date,hardening_completed_date,transplant_date,status,location,notes").order("sow_date", { ascending: false }),
      supabase.from("orchard_crop_successions").select("id,crop_cycle_id,sequence_no,planned_sow_date,planned_transplant_date,planned_plants,germination_rate_pct,seeds_per_plant").order("planned_sow_date"),
      supabase.from("orchard_crop_cycles").select("id,game_plan_id,crop_name,variety").order("crop_name"),
    ])
    const e = p.error ?? l.error ?? m.error ?? b.error ?? s.error ?? c.error
    if (e) setError(`${text.loadError}: ${e.message}`)
    else {
      const nextPlans = (p.data ?? []) as GamePlan[]; const allBatches = (b.data ?? []) as Batch[]; const allSuccessions = (s.data ?? []) as Succession[]; const allCycles = (c.data ?? []) as Cycle[]
      const requested = resolveRequestedGamePlanId(nextPlans, typeof window === "undefined" ? "" : window.location.search); const graph = scopeGamePlanGraph(allCycles, allSuccessions, requested); const nextBatches = scopeBySuccessionId(allBatches, graph.successionIds, requested, (row) => row.crop_succession_id); const scopedBatchIds = new Set(nextBatches.map((row) => row.id))
      setPlans(nextPlans); setSelectedPlanId(requested); setSeedLots((l.data ?? []) as SeedLot[]); setMovements(((m.data ?? []) as SeedMovement[]).filter((row) => !row.nursery_batch_id || requested === ALL_GAME_PLANS || scopedBatchIds.has(row.nursery_batch_id))); setBatches(nextBatches); setSuccessions(graph.scopedSuccessions); setCycles(graph.scopedCycles)
      setProgress(Object.fromEntries(nextBatches.map((item) => [item.id, { emerged_count: item.emerged_count?.toString() ?? "", loss_count: item.loss_count?.toString() ?? "0", loss_reason: item.loss_reason ?? "", ready_count: item.ready_count?.toString() ?? "", hardened_count: item.hardened_count?.toString() ?? "", transplanted_count: item.transplanted_count?.toString() ?? "", hardening_started_date: item.hardening_started_date ?? "", hardening_completed_date: item.hardening_completed_date ?? "", actual_ready_date: item.actual_ready_date ?? "", transplant_date: item.transplant_date ?? "" }])))
    }
    setLoading(false)
  }, [supabase, text.loadError])
  useEffect(() => { void loadData() }, [loadData])

  const selectedPlan = useMemo(() => resolveSelectedGamePlan(plans, selectedPlanId), [plans, selectedPlanId]); const scopeLabel = gamePlanScopeLabel(selectedPlan, text.allPlans)
  const cycleById = useMemo(() => new Map(cycles.map((cycle) => [cycle.id, cycle])), [cycles]); const successionById = useMemo(() => new Map(successions.map((item) => [item.id, item])), [successions]); const seedLotById = useMemo(() => new Map(seedLots.map((item) => [item.id, item])), [seedLots])
  const successionLabel = useCallback((item: Succession) => { const cycle = cycleById.get(item.crop_cycle_id); return `${cycle?.crop_name ?? text.cropFallback}${cycle?.variety ? ` · ${cycle.variety}` : ""} #${item.sequence_no}` }, [cycleById, text.cropFallback]); const cropForSuccession = useCallback((item: Succession | undefined) => item ? (cycleById.get(item.crop_cycle_id)?.crop_name ?? text.cropFallback) : text.cropFallback, [cycleById, text.cropFallback])
  const seedsStartedBySuccession = useMemo(() => { const map = new Map<string, number>(); batches.filter((batch) => !["failed", "cancelled"].includes(batch.status)).forEach((batch) => map.set(batch.crop_succession_id, (map.get(batch.crop_succession_id) ?? 0) + batch.seeds_sown)); return map }, [batches])
  const coverageRows = useMemo(() => { const stock = new Map<string, number>(); seedLots.forEach((lot) => stock.set(cropKey(lot.crop_name, lot.variety), (stock.get(cropKey(lot.crop_name, lot.variety)) ?? 0) + lot.quantity_seeds)); const demand = new Map<string, { label: string; crop: string; required: number }>(); successions.forEach((item) => { const cycle = cycleById.get(item.crop_cycle_id); if (!cycle) return; const outstanding = Math.max(0, estimatedSeeds(item) - (seedsStartedBySuccession.get(item.id) ?? 0)); if (!outstanding) return; const key = cropKey(cycle.crop_name, cycle.variety); const current = demand.get(key) ?? { label: `${cycle.crop_name}${cycle.variety ? ` · ${cycle.variety}` : ""}`, crop: cycle.crop_name, required: 0 }; current.required += outstanding; demand.set(key, current) }); return [...demand.entries()].map(([key, item]) => ({ ...item, stock: stock.get(key) ?? 0, shortage: Math.max(0, item.required - (stock.get(key) ?? 0)) })).sort((a, b) => b.shortage - a.shortage || a.label.localeCompare(b.label)) }, [seedLots, successions, cycleById, seedsStartedBySuccession])
  const queueRows = useMemo(() => successions.map((succession) => { const related = batches.filter((batch) => batch.crop_succession_id === succession.id && !["failed", "cancelled"].includes(batch.status)); const ready = related.reduce((sum, batch) => sum + (batch.ready_count ?? 0), 0); const hardened = related.reduce((sum, batch) => sum + (batch.hardened_count ?? 0), 0); const transplanted = related.reduce((sum, batch) => sum + (batch.transplanted_count ?? 0), 0); const available = Math.max(0, Math.max(ready, hardened) - transplanted); const required = succession.planned_plants ?? 0; return { succession, related, ready, hardened, transplanted, available, required, pct: required > 0 ? Math.round((Math.max(ready, hardened) / required) * 100) : 0 } }).filter((row) => row.available > 0 || row.related.some((batch) => ["hardening", "ready"].includes(batch.status))).sort((a, b) => b.available - a.available), [successions, batches])
  const totalStock = seedLots.reduce((sum, lot) => sum + lot.quantity_seeds, 0); const totalDemand = coverageRows.reduce((sum, item) => sum + item.required, 0); const totalShortage = coverageRows.reduce((sum, item) => sum + item.shortage, 0); const activeBatches = batches.filter((batch) => !["completed", "failed", "cancelled"].includes(batch.status)).length; const readyNow = queueRows.reduce((sum, row) => sum + row.available, 0); const selectedLot = batchForm.seed_lot_id === "none" ? null : seedLotById.get(batchForm.seed_lot_id) ?? null; const requestedSeeds = Number(batchForm.seeds_sown || 0); const hasShortage = Boolean(selectedLot && requestedSeeds > selectedLot.quantity_seeds); const sowingCount = batches.filter((batch) => ["planned", "sown", "germinating"].includes(batch.status)).length; const growingCount = batches.filter((batch) => batch.status === "growing").length; const hardeningCount = batches.filter((batch) => batch.status === "hardening").length

  async function createLot(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!lotForm.crop_name) return; setSaving(true); setError(null); const { error: e } = await supabase.from("orchard_seed_lots").insert({ crop_name: lotForm.crop_name.trim(), variety: lotForm.variety.trim() || null, lot_code: lotForm.lot_code.trim() || null, supplier: lotForm.supplier.trim() || null, quantity_seeds: Number(lotForm.quantity_seeds || 0), germination_rate_pct: lotForm.germination_rate_pct ? Number(lotForm.germination_rate_pct) : null, received_date: lotForm.received_date || null, expiry_date: lotForm.expiry_date || null, storage_location: lotForm.storage_location.trim() || null, notes: lotForm.notes.trim() || null }); if (e) setError(`${text.saveError}: ${e.message}`); else { setLotForm({ crop_name: "", variety: "", lot_code: "", supplier: "", quantity_seeds: "", germination_rate_pct: "", received_date: "", expiry_date: "", storage_location: "", notes: "" }); await loadData() } setSaving(false) }
  function chooseSuccession(value: string) { const item = successionById.get(value); if (!item) return; const outstanding = Math.max(0, estimatedSeeds(item) - (seedsStartedBySuccession.get(item.id) ?? 0)); setBatchForm((current) => ({ ...current, crop_succession_id: value, sow_date: item.planned_sow_date, expected_ready_date: item.planned_transplant_date ?? "", cells_sown: item.planned_plants?.toString() ?? "", seeds_sown: outstanding ? outstanding.toString() : current.seeds_sown })) }
  async function createBatch(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!batchForm.crop_succession_id || !batchForm.sow_date || hasShortage || (selectedPlanId !== ALL_GAME_PLANS && !successionById.has(batchForm.crop_succession_id))) return; setSaving(true); setError(null); const { error: e } = await supabase.from("orchard_nursery_batches").insert({ crop_succession_id: batchForm.crop_succession_id, seed_lot_id: batchForm.seed_lot_id === "none" ? null : batchForm.seed_lot_id, batch_code: batchForm.batch_code.trim() || null, sow_date: batchForm.sow_date, tray_count: numeric(batchForm.tray_count), cells_per_tray: numeric(batchForm.cells_per_tray), cells_sown: numeric(batchForm.cells_sown), seeds_sown: Number(batchForm.seeds_sown || 0), expected_ready_date: batchForm.expected_ready_date || null, location: batchForm.location.trim() || null, notes: batchForm.notes.trim() || null }); if (e) setError(`${text.saveError}: ${e.message}`); else { setBatchForm({ crop_succession_id: "", seed_lot_id: "none", batch_code: "", sow_date: "", tray_count: "", cells_per_tray: "", cells_sown: "", seeds_sown: "", expected_ready_date: "", location: "", notes: "" }); await loadData() } setSaving(false) }
  async function saveProgress(batch: Batch) { if (!batches.some((row) => row.id === batch.id)) return; const item = progress[batch.id] ?? blankProgress; setSaving(true); setError(null); const { error: e } = await supabase.from("orchard_nursery_batches").update({ emerged_count: numeric(item.emerged_count), loss_count: Number(item.loss_count || 0), loss_reason: item.loss_reason.trim() || null, ready_count: numeric(item.ready_count), hardened_count: numeric(item.hardened_count), transplanted_count: numeric(item.transplanted_count), hardening_started_date: item.hardening_started_date || null, hardening_completed_date: item.hardening_completed_date || null, actual_ready_date: item.actual_ready_date || null, transplant_date: item.transplant_date || null, updated_at: new Date().toISOString() }).eq("id", batch.id); if (e) setError(`${text.saveError}: ${e.message}`); else await loadData(); setSaving(false) }
  async function updateStatus(id: string, status: BatchStatus) { if (!batches.some((row) => row.id === id)) return; setSaving(true); setError(null); const patch: Record<string, string> = { status, updated_at: new Date().toISOString() }; const today = localDateKey(); if (status === "hardening") patch.hardening_started_date = today; if (status === "ready") patch.actual_ready_date = today; const { error: e } = await supabase.from("orchard_nursery_batches").update(patch).eq("id", id); if (e) setError(`${text.saveError}: ${e.message}`); else await loadData(); setSaving(false) }
  async function applyAdjustment(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!adjustmentForm.seed_lot_id || !adjustmentForm.quantity_delta) return; let delta = Number(adjustmentForm.quantity_delta); if (adjustmentForm.movement_type === "write_off" && delta > 0) delta *= -1; if ((adjustmentForm.movement_type === "receipt" || adjustmentForm.movement_type === "return") && delta < 0) delta = Math.abs(delta); setSaving(true); setError(null); const { error: e } = await supabase.rpc("orchard_adjust_seed_inventory", { p_seed_lot_id: adjustmentForm.seed_lot_id, p_quantity_delta: delta, p_reason: adjustmentForm.reason.trim(), p_movement_type: adjustmentForm.movement_type, p_occurred_on: adjustmentForm.occurred_on || null }); if (e) setError(`${text.saveError}: ${e.message}`); else { setAdjustmentForm({ seed_lot_id: "", movement_type: "receipt", quantity_delta: "", reason: "", occurred_on: "" }); await loadData() } setSaving(false) }
  async function remove(table: "orchard_seed_lots" | "orchard_nursery_batches", id: string, message: string) { if (table === "orchard_nursery_batches" && !batches.some((row) => row.id === id)) return; if (!window.confirm(message)) return; setSaving(true); setError(null); const { error: e } = await supabase.from(table).delete().eq("id", id); if (e) setError(`${text.saveError}: ${e.message}`); else await loadData(); setSaving(false) }
  function changeScope(value: string) { setSelectedPlanId(value); syncGamePlanQuery(value); setBatchForm((current) => ({ ...current, crop_succession_id: "" })); void loadData() }

  return <AppLayout>
    <PageHeader title={text.title} description={text.description} actions={<div className="flex flex-wrap gap-2"><Select value={selectedPlanId} onValueChange={changeScope}><SelectTrigger className="w-[220px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value={ALL_GAME_PLANS}>{text.allPlans}</SelectItem>{plans.map((plan) => <SelectItem key={plan.id} value={plan.id}>{gamePlanScopeLabel(plan, plan.name)}</SelectItem>)}</SelectContent></Select><Button variant="outline" onClick={() => void loadData()} disabled={loading}><RefreshCw className={`mr-2 h-4 w-4 ${loading ? "animate-spin" : ""}`} />{text.refresh}</Button></div>} />
    <OrchardNavigation />
    <div className="space-y-6 p-4 sm:p-8">
      {error && <Card className="border-destructive/60"><CardContent className="p-4 text-sm text-destructive">{error}</CardContent></Card>}
      <Card><CardContent className="flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="text-xs uppercase tracking-[0.16em] text-muted-foreground">{text.scope}</p><p className="mt-1 font-medium">{scopeLabel}</p></div><p className="max-w-2xl text-xs text-muted-foreground">{text.scopeHelp}</p></CardContent></Card>
      <Card className="overflow-hidden border-white/10 bg-card/80"><CardContent className="p-0"><div className="relative min-h-[210px] overflow-hidden"><img src={NURSERY_HERO} alt={text.heroAlt} className="absolute inset-0 h-full w-full object-cover opacity-100 [filter:none]" /><div className="absolute inset-0" style={{ background: "linear-gradient(90deg, rgba(7,10,8,.94) 0%, rgba(7,10,8,.78) 45%, rgba(7,10,8,.22) 100%)" }} /><div className="relative z-10 grid min-h-[210px] gap-6 p-6 lg:grid-cols-[1.25fr_.75fr] lg:items-end"><div><p className="text-[11px] font-semibold uppercase tracking-[0.22em] text-emerald-200">{text.pipeline}</p><h2 className="mt-2 max-w-xl text-2xl font-semibold tracking-tight text-white sm:text-3xl">{text.pipelineHelp}</h2><div className="mt-5 flex flex-wrap gap-2">{[[text.stock,totalStock],[text.activeBatches,activeBatches],[text.readyNow,readyNow]].map(([label,value]) => <span key={String(label)} className="rounded-full border border-white/15 bg-black/30 px-3 py-1.5 text-xs text-white/80"><span className="font-semibold text-white">{Number(value).toLocaleString(locale)}</span> · {label}</span>)}</div></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-1">{[[text.shortfall,totalShortage],[text.demand,totalDemand],[text.seedLots,seedLots.length]].map(([label,value]) => <div key={String(label)} className="rounded-xl border border-white/15 bg-black/30 p-3"><p className="text-xs text-white/60">{label}</p><p className="mt-1 text-xl font-semibold text-white">{Number(value).toLocaleString(locale)}</p></div>)}</div></div></div></CardContent></Card>
      <Card><CardHeader><CardTitle>{text.pipeline}</CardTitle><CardDescription>{text.pipelineHelp}</CardDescription></CardHeader><CardContent><div className="grid gap-2 lg:grid-cols-5">{[{ label:text.inventoryStage, value:seedLots.length, detail:text.lotsInStock, image:"photo-1589923188900-85dae523342b" },{ label:text.sowingStage, value:sowingCount, detail:text.batchesSown, image:"photo-1416879595882-3373a0480b5b" },{ label:text.nurseryStage, value:growingCount, detail:text.batchesGrowing, image:"photo-1523741543316-beb7fc7023d8" },{ label:text.hardeningStage, value:hardeningCount, detail:text.batchesHardening, image:"photo-1501004318641-b39e6451bec6" },{ label:text.transplantStage, value:readyNow, detail:text.seedlingsReady, image:"photo-1592150621744-aca64f48394a" }].map((stage,index) => <div key={stage.label} className="group relative min-h-[130px] overflow-hidden rounded-xl border"><img src={imageUrl(stage.image,900)} alt="" className="absolute inset-0 h-full w-full object-cover opacity-100 [filter:none]"/><div className="absolute inset-0" style={{ background:"linear-gradient(0deg, rgba(7,10,8,.92) 0%, rgba(7,10,8,.42) 66%, rgba(7,10,8,.14) 100%)" }}/><div className="relative z-10 flex h-full min-h-[130px] flex-col justify-end p-3"><div className="flex items-end justify-between gap-3"><div><p className="text-xs text-white/70">{stage.label}</p><p className="text-2xl font-semibold text-white">{stage.value.toLocaleString(locale)}</p><p className="text-[11px] text-white/60">{stage.detail}</p></div>{index < 4 && <ArrowRight className="h-4 w-4 text-white/45" />}</div></div></div>)}</div></CardContent></Card>
      <div className="grid gap-6 xl:grid-cols-[1.05fr_.95fr]"><Card><CardHeader><CardTitle>{text.coverage}</CardTitle><CardDescription>{text.coverageHelp}</CardDescription></CardHeader><CardContent>{coverageRows.length === 0 ? <p className="py-4 text-sm text-muted-foreground">{text.covered}</p> : <div className="grid gap-3 sm:grid-cols-2">{coverageRows.map((row) => <div key={row.label} className="relative min-h-[150px] overflow-hidden rounded-xl border"><img src={seedPhoto(row.crop)} alt={row.label} className="absolute inset-0 h-full w-full object-cover opacity-100 [filter:none]"/><div className="absolute inset-0 bg-[linear-gradient(0deg,rgba(7,10,8,.94)_0%,rgba(7,10,8,.5)_68%,rgba(7,10,8,.14)_100%)]"/><div className="relative z-10 flex h-full min-h-[150px] flex-col justify-end p-4"><div className="flex items-end justify-between gap-3"><div><p className="font-semibold text-white">{row.label}</p><p className="text-xs text-white/65">{row.required.toLocaleString(locale)} {text.need} · {row.stock.toLocaleString(locale)} {text.onHand}</p></div>{row.shortage > 0 ? <Badge variant="destructive"><AlertTriangle className="mr-1 h-3 w-3" />{row.shortage.toLocaleString(locale)} {text.gap}</Badge> : <Badge variant="secondary">{text.covered}</Badge>}</div></div></div>)}</div>}</CardContent></Card><Card><CardHeader><CardTitle>{text.transplantQueue}</CardTitle><CardDescription>{text.transplantQueueHelp}</CardDescription></CardHeader><CardContent>{queueRows.length === 0 ? <p className="py-4 text-sm text-muted-foreground">{text.noQueue}</p> : <div className="space-y-3">{queueRows.map((row) => { const crop = cropForSuccession(row.succession); return <div key={row.succession.id} className="flex gap-3 rounded-xl border p-3"><img src={batchPhoto("ready",crop)} alt={`${crop} · ${text.readyAlt}`} className="h-20 w-24 rounded-lg object-cover opacity-100 [filter:none]"/><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><p className="font-medium">{successionLabel(row.succession)}</p><p className="text-xs text-muted-foreground">{row.required.toLocaleString(locale)} {text.required} · {row.available.toLocaleString(locale)} {text.availableToMove}</p></div><Badge variant="outline">{row.pct}%</Badge></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full bg-foreground" style={{ width: `${Math.max(0, Math.min(100, row.pct))}%` }} /></div></div></div>})}</div>}</CardContent></Card></div>
      <div className="grid gap-6 xl:grid-cols-2"><Card><CardHeader><CardTitle>{text.newSeedLot}</CardTitle><CardDescription>{seedLots.length} {text.available}</CardDescription></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-2" onSubmit={createLot}><Field label={text.crop}><Input value={lotForm.crop_name} onChange={(e) => setLotForm((v) => ({ ...v, crop_name: e.target.value }))} required /></Field><Field label={text.variety}><Input value={lotForm.variety} onChange={(e) => setLotForm((v) => ({ ...v, variety: e.target.value }))} /></Field><Field label={text.lot}><Input value={lotForm.lot_code} onChange={(e) => setLotForm((v) => ({ ...v, lot_code: e.target.value }))} /></Field><Field label={text.supplier}><Input value={lotForm.supplier} onChange={(e) => setLotForm((v) => ({ ...v, supplier: e.target.value }))} /></Field><Field label={text.quantity}><Input type="number" min="0" value={lotForm.quantity_seeds} onChange={(e) => setLotForm((v) => ({ ...v, quantity_seeds: e.target.value }))} /></Field><Field label={text.germination}><Input type="number" min="1" max="100" step="0.1" value={lotForm.germination_rate_pct} onChange={(e) => setLotForm((v) => ({ ...v, germination_rate_pct: e.target.value }))} /></Field><Field label={text.received}><Input type="date" value={lotForm.received_date} onChange={(e) => setLotForm((v) => ({ ...v, received_date: e.target.value }))} /></Field><Field label={text.expiry}><Input type="date" value={lotForm.expiry_date} onChange={(e) => setLotForm((v) => ({ ...v, expiry_date: e.target.value }))} /></Field><Field label={text.storage}><Input value={lotForm.storage_location} onChange={(e) => setLotForm((v) => ({ ...v, storage_location: e.target.value }))} /></Field><div className="md:col-span-2"><Field label={text.notes}><Textarea value={lotForm.notes} onChange={(e) => setLotForm((v) => ({ ...v, notes: e.target.value }))} /></Field></div><div className="md:col-span-2"><Button type="submit" disabled={saving}><Plus className="mr-2 h-4 w-4" />{text.saveLot}</Button></div></form></CardContent></Card><Card><CardHeader><CardTitle>{text.newBatch}</CardTitle><CardDescription>{text.partialBatch}</CardDescription></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-2" onSubmit={createBatch}><Field label={text.succession}><Select value={batchForm.crop_succession_id} onValueChange={chooseSuccession}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{successions.map((item) => <SelectItem key={item.id} value={item.id}>{successionLabel(item)}</SelectItem>)}</SelectContent></Select></Field><Field label={text.seedLot}><Select value={batchForm.seed_lot_id} onValueChange={(value) => setBatchForm((v) => ({ ...v, seed_lot_id: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">{text.none}</SelectItem>{seedLots.map((lot) => <SelectItem key={lot.id} value={lot.id}>{lot.crop_name}{lot.variety ? ` · ${lot.variety}` : ""}{lot.lot_code ? ` · ${lot.lot_code}` : ""} · {lot.quantity_seeds.toLocaleString(locale)}</SelectItem>)}</SelectContent></Select></Field><Field label={text.batchCode}><Input value={batchForm.batch_code} onChange={(e) => setBatchForm((v) => ({ ...v, batch_code: e.target.value }))} /></Field><Field label={text.sowDate}><Input type="date" value={batchForm.sow_date} onChange={(e) => setBatchForm((v) => ({ ...v, sow_date: e.target.value }))} required /></Field><Field label={text.trays}><Input type="number" min="0" value={batchForm.tray_count} onChange={(e) => setBatchForm((v) => ({ ...v, tray_count: e.target.value }))} /></Field><Field label={text.cellsPerTray}><Input type="number" min="1" value={batchForm.cells_per_tray} onChange={(e) => setBatchForm((v) => ({ ...v, cells_per_tray: e.target.value }))} /></Field><Field label={text.cells}><Input type="number" min="0" value={batchForm.cells_sown} onChange={(e) => setBatchForm((v) => ({ ...v, cells_sown: e.target.value }))} /></Field><Field label={text.seedsSown}><Input type="number" min="0" value={batchForm.seeds_sown} onChange={(e) => setBatchForm((v) => ({ ...v, seeds_sown: e.target.value }))} required /></Field><Field label={text.expectedReady}><Input type="date" value={batchForm.expected_ready_date} onChange={(e) => setBatchForm((v) => ({ ...v, expected_ready_date: e.target.value }))} /></Field><Field label={text.location}><Input value={batchForm.location} onChange={(e) => setBatchForm((v) => ({ ...v, location: e.target.value }))} /></Field><div className="md:col-span-2"><Field label={text.notes}><Textarea value={batchForm.notes} onChange={(e) => setBatchForm((v) => ({ ...v, notes: e.target.value }))} /></Field></div>{selectedLot && <div className="md:col-span-2 text-xs text-muted-foreground">{selectedLot.quantity_seeds.toLocaleString(locale)} {text.onHand} · {text.inventoryAuto}</div>}{hasShortage && <div className="md:col-span-2 text-sm text-destructive">{text.shortage}</div>}<div className="md:col-span-2"><Button type="submit" disabled={saving || hasShortage || !batchForm.crop_succession_id}><Sprout className="mr-2 h-4 w-4" />{text.startBatch}</Button></div></form></CardContent></Card></div>
      <Card><CardHeader><CardTitle>{text.stockBoard}</CardTitle></CardHeader><CardContent>{seedLots.length === 0 ? <p className="py-6 text-sm text-muted-foreground">{text.emptyLots}</p> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{seedLots.map((lot) => <div key={lot.id} className="group overflow-hidden rounded-xl border"><div className="relative h-36 overflow-hidden"><img src={seedPhoto(lot.crop_name)} alt={lot.crop_name} className="h-full w-full object-cover opacity-100 [filter:none]"/><div className="absolute inset-0 bg-[linear-gradient(0deg,rgba(7,10,8,.9)_0%,rgba(7,10,8,.08)_75%)]"/><div className="absolute bottom-3 left-3 right-3 flex items-end justify-between gap-3"><div><p className="font-semibold text-white">{lot.crop_name}{lot.variety ? ` · ${lot.variety}` : ""}</p><p className="text-xs text-white/65">{lot.lot_code || lot.supplier || "—"}</p></div><Button variant="secondary" size="icon" aria-label={text.deleteLot} className="h-8 w-8 bg-black/45 text-white" onClick={() => void remove("orchard_seed_lots", lot.id, text.deleteLot)}><Trash2 className="h-4 w-4" /></Button></div></div><div className="p-4"><div className="flex flex-wrap gap-2"><Badge variant="secondary">{lot.quantity_seeds.toLocaleString(locale)} {text.available}</Badge>{lot.germination_rate_pct && <Badge variant="outline">{lot.germination_rate_pct}%</Badge>}</div><p className="mt-3 text-xs text-muted-foreground">{lot.storage_location || ""}{lot.expiry_date ? ` · ${text.expiry}: ${dateLabel(lot.expiry_date, locale)}` : ""}</p></div></div>)}</div>}</CardContent></Card>
      <Card><CardHeader><CardTitle>{text.batchBoard}</CardTitle><CardDescription>{text.inventoryAuto}</CardDescription></CardHeader><CardContent>{loading ? <p className="py-6 text-sm text-muted-foreground">{text.loading}</p> : batches.length === 0 ? <p className="py-6 text-sm text-muted-foreground">{text.emptyBatches}</p> : <div className="grid gap-4 xl:grid-cols-2">{batches.map((batch) => { const succession = successionById.get(batch.crop_succession_id); const crop = cropForSuccession(succession); const item = progress[batch.id] ?? blankProgress; const emerged = batch.emerged_count ?? 0; const mortalityPct = emerged > 0 ? Math.round((batch.loss_count / emerged) * 100) : 0; const trayCapacity = (batch.tray_count ?? 0) * (batch.cells_per_tray ?? 0); return <div key={batch.id} className="overflow-hidden rounded-xl border"><div className="relative h-40 overflow-hidden"><img src={batchPhoto(batch.status,crop)} alt={`${crop} · ${statusLabel(batch.status)}`} className="h-full w-full object-cover opacity-100 [filter:none]"/><div className="absolute inset-0 bg-[linear-gradient(0deg,rgba(7,10,8,.92)_0%,rgba(7,10,8,.18)_72%)]"/><div className="absolute inset-x-0 bottom-0 p-4"><div className="flex items-end justify-between gap-3"><div><p className="font-semibold text-white">{succession ? successionLabel(succession) : text.succession}</p><p className="text-xs text-white/65">{dateLabel(batch.sow_date, locale)} → {dateLabel(batch.expected_ready_date, locale)}{batch.location ? ` · ${batch.location}` : ""}</p></div><Badge className="bg-black/50 text-white">{statusLabel(batch.status)}</Badge></div></div></div><div className="p-4"><div className="flex flex-wrap gap-2"><Badge variant="outline">{batch.seeds_sown.toLocaleString(locale)} {text.seedsSown.toLowerCase()}</Badge>{batch.cells_sown != null && <Badge variant="secondary">{batch.cells_sown.toLocaleString(locale)} {text.cells.toLowerCase()}</Badge>}{trayCapacity > 0 && <Badge variant="outline">{trayCapacity.toLocaleString(locale)} {text.capacity.toLowerCase()}</Badge>}<Badge variant="outline">{mortalityPct}% {text.mortality.toLowerCase()}</Badge></div><div className="mt-4 flex gap-2"><Select value={batch.status} onValueChange={(value) => void updateStatus(batch.id, value as BatchStatus)}><SelectTrigger className="w-[155px]"><SelectValue /></SelectTrigger><SelectContent>{statuses.map((status) => <SelectItem key={status} value={status}>{statusLabel(status)}</SelectItem>)}</SelectContent></Select><Button variant="ghost" size="icon" aria-label={text.deleteBatch} onClick={() => void remove("orchard_nursery_batches", batch.id, text.deleteBatch)}><Trash2 className="h-4 w-4" /></Button></div><div className="mt-4 grid gap-3 border-t pt-4 sm:grid-cols-2 xl:grid-cols-5"><Field label={text.emerged}><Input type="number" min="0" value={item.emerged_count} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, emerged_count: e.target.value } }))} /></Field><Field label={text.losses}><Input type="number" min="0" value={item.loss_count} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, loss_count: e.target.value } }))} /></Field><Field label={text.ready}><Input type="number" min="0" value={item.ready_count} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, ready_count: e.target.value } }))} /></Field><Field label={text.hardened}><Input type="number" min="0" value={item.hardened_count} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, hardened_count: e.target.value } }))} /></Field><Field label={text.transplanted}><Input type="number" min="0" value={item.transplanted_count} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, transplanted_count: e.target.value } }))} /></Field><Field label={text.hardeningStart}><Input type="date" value={item.hardening_started_date} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, hardening_started_date: e.target.value } }))} /></Field><Field label={text.hardeningEnd}><Input type="date" value={item.hardening_completed_date} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, hardening_completed_date: e.target.value } }))} /></Field><Field label={text.actualReady}><Input type="date" value={item.actual_ready_date} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, actual_ready_date: e.target.value } }))} /></Field><Field label={text.transplantDate}><Input type="date" value={item.transplant_date} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, transplant_date: e.target.value } }))} /></Field><Field label={text.lossReason}><Input value={item.loss_reason} onChange={(e) => setProgress((p) => ({ ...p, [batch.id]: { ...item, loss_reason: e.target.value } }))} /></Field></div><Button className="mt-4" variant="outline" onClick={() => void saveProgress(batch)} disabled={saving}>{text.saveCounts}</Button></div></div> })}</div>}</CardContent></Card>
      <div className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><Card><CardHeader><CardTitle>{text.adjustment}</CardTitle><CardDescription>{text.adjustmentHelp}</CardDescription></CardHeader><CardContent><form className="space-y-4" onSubmit={applyAdjustment}><Field label={text.seedLot}><Select value={adjustmentForm.seed_lot_id} onValueChange={(value) => setAdjustmentForm((v) => ({ ...v, seed_lot_id: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{seedLots.map((lot) => <SelectItem key={lot.id} value={lot.id}>{lot.crop_name}{lot.variety ? ` · ${lot.variety}` : ""}{lot.lot_code ? ` · ${lot.lot_code}` : ""}</SelectItem>)}</SelectContent></Select></Field><div className="grid gap-3 sm:grid-cols-2"><Field label={text.movementType}><Select value={adjustmentForm.movement_type} onValueChange={(value) => setAdjustmentForm((v) => ({ ...v, movement_type: value as AdjustmentType }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{adjustmentTypes.map((type) => <SelectItem key={type} value={type}>{adjustmentLabel(type)}</SelectItem>)}</SelectContent></Select></Field><Field label={text.signedQuantity}><Input type="number" value={adjustmentForm.quantity_delta} onChange={(e) => setAdjustmentForm((v) => ({ ...v, quantity_delta: e.target.value }))} required /></Field></div><Field label={text.reason}><Textarea value={adjustmentForm.reason} onChange={(e) => setAdjustmentForm((v) => ({ ...v, reason: e.target.value }))} /></Field><Field label={text.date}><Input type="date" value={adjustmentForm.occurred_on} onChange={(e) => setAdjustmentForm((v) => ({ ...v, occurred_on: e.target.value }))} /></Field><Button type="submit" disabled={saving || !adjustmentForm.seed_lot_id}><PackageOpen className="mr-2 h-4 w-4"/>{text.applyAdjustment}</Button></form></CardContent></Card><Card><CardHeader><CardTitle>{text.movementHistory}</CardTitle></CardHeader><CardContent>{movements.length === 0 ? <p className="py-4 text-sm text-muted-foreground">{text.noMovements}</p> : <div className="max-h-[420px] space-y-2 overflow-auto pr-1">{movements.map((movement) => { const lot = seedLotById.get(movement.seed_lot_id); return <div key={movement.id} className="flex items-center justify-between gap-3 rounded-lg border p-3"><div className="min-w-0"><p className="truncate text-sm font-medium">{lot ? `${lot.crop_name}${lot.variety ? ` · ${lot.variety}` : ""}` : text.seedLot}</p><p className="text-xs text-muted-foreground">{movementLabel(movement.movement_type)} · {dateLabel(movement.occurred_on, locale)}{movement.reason ? ` · ${movement.reason}` : ""}</p></div><Badge variant={movement.quantity_delta < 0 ? "outline" : "secondary"}>{movement.quantity_delta > 0 ? "+" : ""}{movement.quantity_delta.toLocaleString(locale)}</Badge></div> })}</div>}</CardContent></Card></div>
      <Card><CardContent className="flex items-center gap-3 p-4 text-xs text-muted-foreground"><History className="h-4 w-4 shrink-0" />{text.inventoryAuto}</CardContent></Card>
    </div>
  </AppLayout>
}

function Field({ label, children }: { label: string; children: ReactNode }) { return <div className="space-y-2"><Label>{label}</Label>{children}</div> }
